import type { BiomarkerInput, DrugInput, EntityInput, PaperInput, PathwayInput, TargetInput, TrialInput } from "@/lib/schema";
import type { Spike, SpikeSupplement } from "./index";

/**
 * TRIPLE-NEGATIVE BREAST CANCER, MOLECULAR LAYER. Facts checked 2026-09-24.
 *
 * The genomic landscape of triple-negative breast cancer as a sourced table (`tnbcMolecularLandscape`), the Lehmann
 * and Burstein transcriptomic subtypes with their published therapy implications, the regional and ancestry
 * differences, the ctDNA and molecular residual disease studies, and the biomarker readouts, targets, tests and
 * antibody-drug conjugates that follow from it; and paper records for every landscape paper cited.
 *
 * Sources and rules. Every frequency names its cohort, its size and the paper it was read from. Figures marked
 * "cBioPortal" were computed on 24 Sept 2026 from the public cBioPortal API (read-only) on the named study id, on a
 * triple-negative subset built from the study's own clinical attributes: for brca_tcga_pub (TCGA, Nature 2012) the
 * samples recorded ER-negative, PR-negative and HER2-negative (123 of 818; the same patients were then read in
 * brca_tcga_pan_can_atlas_2018 for the 2018 mutation calls, TMB and MSIsensor scores); for brca_metabric the samples
 * recorded negative for all three (320 of 2,469; 299 with the 173-gene mutation panel); for breast_msk_2018 (Razavi,
 * Cancer Cell 2018) the 176 samples from the 168 patients whose overall receptor status is "Triple Negative" (91
 * primaries, 85 metastases, MSK-IMPACT). A frequency is the count of samples carrying a non-synonymous mutation (or a
 * high-level amplification / deep deletion in the discrete copy-number profile) over that subset. They are
 * sample-level frequencies for the study as deposited, not the paper's own percentages, which are quoted alongside
 * where an abstract or open-access full text gives them. Nothing is invented and no OncoKB or COSMIC data was used.
 * Abstract text was read from Europe PMC.
 *
 * Cancer id. The corpus cancer record is `tnbc` (src/data/cancers.ts, with the tnbc-early and tnbc-metastatic
 * children in breast-subtypes.ts); this file patches it. Every reference goes through TNBC_CANCER_ID.
 *
 * Terms and trials are not created here (the owner's brief for this layer); the report lists the ones the layer
 * would link to (Lehmann subtypes, basal-like, luminal androgen receptor, HRDetect, BRCA1 promoter methylation, TNT,
 * LOTUS, PAKT, CAPItello-290, c-TRAK TN, BRE12-158, ZEST, TBCRC 011, SCAN-B).
 */
export const TNBC_CANCER_ID = "tnbc";
const TN = TNBC_CANCER_ID;
const asOf = "2026-09-24";

const doi = (d: string) => `https://doi.org/${d}`;
const pubmed = (pmid: string) => `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`;
const cbio = (study: string) => `https://www.cbioportal.org/study/summary?id=${study}`;

type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, ...x });
/** A partial record for an entity another file owns; arrays append, scalars fill gaps only (see applySpikeSupplements). */
const sup = <T extends EntityInput>(x: { id: string } & Partial<Omit<T, "id" | "kind">>): SpikeSupplement => x as SpikeSupplement;

