// ======================= THE LANDSCAPE TABLE =======================
/**
 * One row per gene or measurement. `pct` is the headline figure for the prevalence matrix (a number, or a range string
 * like "10-18"); `frequency` spells out every cohort behind it. `targetId` is omitted where the corpus has no target
 * record (MYC amplification, HRD, TMB, MSI, TILs).
 */
export type TnbcLandscapeRow = {
  gene: string;
  /** Corpus target id (src/data/targets*.ts); composite targets (brca, mmr, akt) stand for their gene families. */
  targetId?: string;
  alteration: string;
  /** Headline figure for the prevalence matrix: 0 to 100, or a range string. */
  pct: number | string;
  /** Every frequency with its cohort, size and paper. */
  frequency: string;
  /** Comparison between cohorts, subtypes or assays, when a source makes one. */
  contrast?: string;
  sources: Array<{ label: string; url: string }>;
};

